#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

bool containsRotated(const std::vector<int>& a, int target) {
    // 이 자료의 크기 계약: 최대 100000개이므로 int 인덱스가 안전합니다.
    int left = 0, right = static_cast<int>(a.size()) - 1;
    while (left <= right) {
        const int mid = left + (right - left) / 2;
        if (a[mid] == target) return true;
        if (a[left] == a[mid] && a[mid] == a[right]) {
            // mid는 목표가 아니므로 같은 값인 양 끝도 안전하게 제외합니다.
            ++left;
            --right;
        } else if (a[left] <= a[mid]) {
            // 왼쪽 구간이 정렬되어 있습니다.
            if (a[left] <= target && target < a[mid]) right = mid - 1;
            else left = mid + 1;
        } else {
            // 오른쪽 구간이 정렬되어 있습니다.
            if (a[mid] < target && target <= a[right]) left = mid + 1;
            else right = mid - 1;
        }
    }
    return false;
}

long long cases = 0;
void check(const std::vector<int>& sorted) {
    if (sorted.empty()) {
        for (int target = -1; target <= 4; ++target) {
            assert(!containsRotated(sorted, target));
            ++cases;
        }
        return;
    }
    for (std::size_t shift = 0; shift < sorted.size(); ++shift) {
        std::vector<int> a = sorted;
        std::rotate(a.begin(), a.begin() + static_cast<std::ptrdiff_t>(shift), a.end());
        for (int target = -1; target <= 4; ++target) {
            const bool reference = std::find(a.begin(), a.end(), target) != a.end();
            assert(containsRotated(a, target) == reference);
            ++cases;
        }
    }
}
void generate(int remaining, int minimum, std::vector<int>& cur) {
    if (remaining == 0) { check(cur); return; }
    for (int value = minimum; value <= 3; ++value) {
        cur.push_back(value);
        generate(remaining - 1, value, cur);
        cur.pop_back();
    }
}
int main() {
    std::vector<int> cur;
    for (int size = 0; size <= 8; ++size) generate(size, 0, cur);
    assert(containsRotated({2,2,2,3,1,2}, 1));
    assert(!containsRotated({2,2,2,2}, 1));
    std::cout << "rotated search comparisons: " << cases << '\n';
}
